/**
 * Timed server commands for `run_map_test`.
 *
 * A test that has to look at the game four minutes in cannot wait on the console: the harness
 * reads the log as it grows and its post-match screenshot waits seconds, not minutes. The one
 * thing that reliably runs late is a map entity, so this writes a small Squirrel file that
 * spawns a `logic_timer` per entry and points it at a `point_servercommand`; the timer's
 * `OnTimer` output runs the command on the server at the requested second.
 *
 * The generated file is installed into `scripts/vscripts` and started with
 * `script_execute hsmcp_schedule`.
 */

export interface ScheduleEntry {
  atSeconds: number;
  command: string;
}

/** `AddOutput` carries its fields comma-separated, so these cannot travel through it. */
const REJECTED = /[",\r\n]/;

function squirrelString(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

export function scheduleScript(entries: readonly ScheduleEntry[]): string {
  if (entries.length === 0) return "";
  for (const entry of entries) {
    if (!Number.isFinite(entry.atSeconds) || entry.atSeconds <= 0) {
      throw new Error(`schedule: atSeconds must be positive, got ${entry.atSeconds}`);
    }
    if (entry.command.trim() === "") {
      throw new Error("schedule: a command cannot be empty");
    }
    if (REJECTED.test(entry.command)) {
      throw new Error(
        `schedule: ${JSON.stringify(entry.command)} cannot be scheduled -- AddOutput passes ` +
          "its command comma-separated, so a comma, a double quote or a newline has no way " +
          "through",
      );
    }
  }

  const lines = [
    "// Generated by run_map_test: server commands at fixed seconds.",
    `printl("[HSMCP] schedule armed with ${entries.length} entries");`,
    "",
    "function hsmcp_schedule_timer( name, seconds, text )",
    "{",
    '\tlocal timer = SpawnEntityFromTable( "logic_timer", { targetname = name, RefireTime = seconds, StartDisabled = 0 } );',
    "\tif ( timer == null )",
    "\t{",
    '\t\tprintl( "[HSMCP] schedule: could not spawn " + name );',
    "\t\treturn;",
    "\t}",
    '\tEntFire( name, "AddOutput", "OnTimer hsmcp_sched_cmd,Command," + text + ",0,1" );',
    "}",
    "",
    'SpawnEntityFromTable( "point_servercommand", { targetname = "hsmcp_sched_cmd" } );',
  ];
  entries.forEach((entry, index) => {
    const name = `hsmcp_sched_${index + 1}`;
    lines.push(
      `hsmcp_schedule_timer( "${name}", ${entry.atSeconds.toFixed(1)}, "${squirrelString(entry.command)}" );`,
    );
  });
  return `${lines.join("\n")}\n`;
}

/** The file name the generated script is installed under. */
export const SCHEDULE_FILE = "hsmcp_schedule.nut";
